mapper.select:
SELECT t.id AS id, t.title AS title, c.name AS course_name, t.start_date AS start_date, t.end_date AS end_date, t.test_time AS test_time, ( SELECT COUNT(*) FROM test_submission ts WHERE ts.test_id = t.id AND ts.submission_status = 'COMPLETED' ) AS completed_count, c.number_of_learner AS number_of_learner FROM test t JOIN course c ON t.course_id = c.id LEFT JOIN test_submission ts ON ts.test_id = t.id AND ts.submission_status = 'COMPLETE' WHERE t.deleted_at IS NULL
AND c.name = #{courseName}
GROUP BY t.id, t.title, c.name, t.start_date, t.end_date, t.test_time, c.number_of_learner ORDER BY t.id DESC LIMIT #{requestVO.skip}, #{requestVO.pageSize}

SELECT COUNT(*) FROM ( SELECT t.id FROM test t JOIN course c ON t.course_id = c.id LEFT JOIN test_submission ts ON ts.test_id = t.id AND ts.submission_status = 'COMPLETE' WHERE t.deleted_at IS NULL
AND c.name = #{courseName}
GROUP BY t.id ) AS count_table
